import React, { useState } from "react";
import { LuInstagram } from "react-icons/lu";

import { BROKERAGE } from "../ppm/config/profile--business-name";
import {
  EMAIL,
  EMAIL_HREF,
  INSTAGRAM_URL,
  LOCATION,
  PHONE_DISPLAY,
  PHONE_HREF,
} from "../ppm/config/profile--contact";
import { CONTACT_TOPICS } from "./content";
import { useEnquirySubmit } from "./InquiryForm";

type Status = "idle" | "sending" | "sent";

/**
 * The template's "Get in touch" section: contact details on the left, a white
 * form card with underline fields on the right. Submissions go through the same
 * handler as every other enquiry form on the site.
 */
export default function ContactSection({ title = "Get in touch" }: { title?: string }) {
  const submit = useEnquirySubmit();
  const [status, setStatus] = useState<Status>("idle");
  const [error, setError] = useState("");

  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = event.currentTarget;
    const data = new FormData(form);
    setStatus("sending");
    setError("");
    try {
      await submit({
        fullName: String(data.get("fullName") ?? ""),
        email: String(data.get("email") ?? ""),
        phone: String(data.get("phone") ?? ""),
        reason: String(data.get("reason") ?? ""),
        message: String(data.get("message") ?? ""),
      });
      form.reset();
      setStatus("sent");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Something went wrong. Please try again.");
      setStatus("idle");
    }
  };

  return (
    <section id="contact" className="sbs-ct">
      <div className="sbs-wrap sbs-ct__grid">
        <div>
          <h2 className="sbs-ct__title">{title}</h2>
          <p className="sbs-ct__pre">
            Buying, selling or just curious what your home is worth? A conversation is the easiest place to start.
          </p>
          <div className="sbs-ct__info">
            <div>
              <h4>Serving:</h4>
              <span>
                {LOCATION}
                <br />
                &amp; the Treasure Valley
              </span>
            </div>
            <div>
              <h4>Phone:</h4>
              <a href={PHONE_HREF}>{PHONE_DISPLAY}</a>
            </div>
            <div>
              <h4>Email:</h4>
              <a href={EMAIL_HREF}>{EMAIL}</a>
            </div>
            <div>
              <h4>Social:</h4>
              <a href={INSTAGRAM_URL} target="_blank" rel="noreferrer" aria-label="Instagram" className="sbs-ct__social">
                <LuInstagram size={20} />
              </a>
            </div>
          </div>
          <p className="sbs-ct__broker">{BROKERAGE}</p>
        </div>

        <div className="sbs-ct__card">
          <h3 className="sbs-ct__formtitle">
            Ready to make your move?
            <br />
            Start with a <span>“Hello”</span>
          </h3>

          {status === "sent" ? (
            <div className="sbs-ct__sent" role="status">
              <h4>Message sent</h4>
              <p>Thank you. Sajra will be in touch shortly.</p>
              <button type="button" className="sbs-ct__again" onClick={() => setStatus("idle")}>
                Send another message
              </button>
            </div>
          ) : (
            <form onSubmit={onSubmit} className="sbs-ct__form">
              <input name="fullName" type="text" placeholder="Your name" aria-label="Your name" required />
              <input name="email" type="email" placeholder="Your email" aria-label="Your email" required />
              <input name="phone" type="tel" placeholder="Your phone (optional)" aria-label="Your phone" />
              <select name="reason" aria-label="I am interested in" required defaultValue="">
                <option value="" disabled>
                  I’m interested in…
                </option>
                {CONTACT_TOPICS.map((topic) => (
                  <option key={topic.value} value={topic.value}>
                    {topic.label}
                  </option>
                ))}
              </select>
              <textarea name="message" placeholder="Message" aria-label="Message" required />
              {error ? (
                <p className="sbs-ct__error" role="alert">
                  {error}
                </p>
              ) : null}
              <button type="submit" disabled={status === "sending"}>
                {status === "sending" ? "Sending…" : "Send Message"}
              </button>
            </form>
          )}
        </div>
      </div>
    </section>
  );
}
