import React, { useMemo } from "react";
import { Link } from "gatsby";
import { LuArrowUpRight, LuInstagram } from "react-icons/lu";

import { AGENT_NAME, BROKERAGE } from "../ppm/config/profile--business-name";
import {
  INSTAGRAM_HANDLE,
  INSTAGRAM_URL,
  PHONE_DISPLAY,
  PHONE_HREF,
} from "../ppm/config/profile--contact";
import { Btn, SectionHead } from "./Chrome";
import { townOf, useListings } from "./Listings";
import { COMMUNITIES, INSTAGRAM_TILES, PORTRAIT, STATS } from "./content";

export { default as Hero } from "./Hero";

export function Stats() {
  return (
    <section className="sbs-stats" aria-label="Sajra at a glance">
      <div className="sbs-wrap sbs-stats__grid">
        {STATS.map((stat) => (
          <div className="sbs-stat" key={stat.label}>
            <b>{stat.value}</b>
            <span>{stat.label}</span>
          </div>
        ))}
      </div>
    </section>
  );
}

export { default as About } from "./About";

export function Communities() {
  const all = useListings();
  const counts = useMemo(() => {
    const map = new Map<string, number>();
    all.forEach((p) => map.set(townOf(p), (map.get(townOf(p)) ?? 0) + 1));
    return map;
  }, [all]);

  return (
    <section id="communities" className="sbs-section">
      <div className="sbs-wrap sbs-cm">
        <div className="sbs-cm__intro">
          <SectionHead
            eyebrow="Communities"
            title="Serving the heart of the Treasure Valley"
            lede="From downtown Boise to the growing suburbs, Sajra knows these communities inside and out."
          />
          <div style={{ marginTop: 36 }}>
            <Btn to="/properties/">Browse all listings</Btn>
          </div>
        </div>
        <ol className="sbs-cm__list">
          {COMMUNITIES.map((town, i) => {
            const n = counts.get(town) ?? 0;
            return (
              <li key={town}>
                <Link to={`/properties/?town=${encodeURIComponent(town)}`}>
                  <span className="sbs-cm__num">{String(i + 1).padStart(2, "0")}</span>
                  <span className="sbs-cm__name">{town}</span>
                  <span className="sbs-cm__count">{n ? `${n} ${n === 1 ? "home" : "homes"}` : "Ask Sajra"}</span>
                  <LuArrowUpRight size={22} aria-hidden="true" />
                </Link>
              </li>
            );
          })}
        </ol>
      </div>
    </section>
  );
}

export function Instagram() {
  return (
    <section className="sbs-section sbs-alt">
      <div className="sbs-wrap">
        <div className="sbs-head-row">
          <SectionHead eyebrow="Follow the journey" title={`@${INSTAGRAM_HANDLE}`} />
          <Btn href={INSTAGRAM_URL}>Follow on Instagram</Btn>
        </div>
        <div className="sbs-ig">
          {INSTAGRAM_TILES.map((tile) => (
            <a key={tile.src} href={INSTAGRAM_URL} target="_blank" rel="noreferrer" aria-label="Open Instagram">
              <img src={tile.src} alt={tile.alt} loading="lazy" />
              <span className="sbs-ig__over">
                <LuInstagram size={28} aria-hidden="true" />
                <em>View on Instagram</em>
              </span>
            </a>
          ))}
        </div>
      </div>
    </section>
  );
}

