import React, { useMemo, useState } from "react";
import { Link, navigate } from "gatsby";
import { LuArrowUpRight, LuPhone, LuSearch } from "react-icons/lu";

import { AGENT_NAME, BROKERAGE } from "../ppm/config/profile--business-name";
import { PHONE_DISPLAY, PHONE_HREF } from "../ppm/config/profile--contact";
import { Btn } from "./Chrome";
import { COMMUNITIES, HERO_IMAGE, PORTRAIT } from "./content";
import { useListings } from "./Listings";

const PRICES = [400000, 600000, 800000, 1000000, 1500000, 2000000];
const money = (n: number) => (n >= 1_000_000 ? `$${n / 1_000_000}M` : `$${n / 1000}K`);
const FALLBACK_TYPES = ["Single Family", "Townhome", "Condo"];

/** Buy / Sell panel. "Buy" sends the visitor to /properties with the filters applied. */
function SearchPanel() {
  const all = useListings();
  const [mode, setMode] = useState<"buy" | "sell">("buy");
  const types = useMemo(() => {
    const found = Array.from(new Set(all.map((p) => p.type))).sort();
    return found.length ? found : FALLBACK_TYPES;
  }, [all]);

  const onSearch = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    const params = new URLSearchParams();
    (["town", "type", "max", "beds"] as const).forEach((key) => {
      const value = String(data.get(key) ?? "");
      if (value) params.set(key, value);
    });
    navigate(`/properties/${params.toString() ? `?${params}` : ""}`);
  };

  return (
    <div className="sbs-find">
      <div className="sbs-find__tabs" role="tablist" aria-label="What would you like to do?">
        <button type="button" role="tab" aria-selected={mode === "buy"} className={mode === "buy" ? "is-on" : undefined} onClick={() => setMode("buy")}>
          Buy
        </button>
        <button type="button" role="tab" aria-selected={mode === "sell"} className={mode === "sell" ? "is-on" : undefined} onClick={() => setMode("sell")}>
          Sell
        </button>
      </div>

      {mode === "buy" ? (
        <form className="sbs-find__form" onSubmit={onSearch}>
          <label>
            <span>Location</span>
            <select name="town" defaultValue="">
              <option value="">All Treasure Valley</option>
              {COMMUNITIES.map((town) => (
                <option key={town}>{town}</option>
              ))}
            </select>
          </label>
          <label>
            <span>Home type</span>
            <select name="type" defaultValue="">
              <option value="">Any type</option>
              {types.map((type) => (
                <option key={type}>{type}</option>
              ))}
            </select>
          </label>
          <label>
            <span>Max price</span>
            <select name="max" defaultValue="">
              <option value="">No limit</option>
              {PRICES.map((price) => (
                <option key={price} value={price}>
                  Up to {money(price)}
                </option>
              ))}
            </select>
          </label>
          <label>
            <span>Bedrooms</span>
            <select name="beds" defaultValue="">
              <option value="">Any</option>
              {[2, 3, 4, 5].map((n) => (
                <option key={n} value={n}>
                  {n}+ beds
                </option>
              ))}
            </select>
          </label>
          <button type="submit" className="sbs-find__go">
            <LuSearch size={18} aria-hidden="true" /> Search homes
          </button>
        </form>
      ) : (
        <div className="sbs-find__sell">
          <p>
            <b>Thinking of selling?</b> Talk through pricing, timing and prep with Sajra, with no obligation.
          </p>
          <Link to="/contact/?topic=selling" className="sbs-find__go">
            Talk to Sajra <LuArrowUpRight size={17} aria-hidden="true" />
          </Link>
        </div>
      )}
    </div>
  );
}

/** The homepage hero: a full-bleed home photograph, a headline and a home search. */
export default function Hero() {
  return (
    <section className="sbs-hero2">
      <img className="sbs-hero2__bg" src={HERO_IMAGE} alt="" loading="eager" decoding="async" />
      <div className="sbs-hero2__shade" />

      <div className="sbs-wrap sbs-hero2__inner">
        <div className="sbs-hero2__copy">
          <span className="sbs-hero2__pill">Boise, Idaho REALTOR® · {BROKERAGE}</span>
          <h1>
            Find the right home
            <br />
            in the Treasure Valley
          </h1>
          <p>
            Helping Treasure Valley families buy, sell, and invest with honesty, hard work, and a local’s eye for a
            home’s potential.
          </p>
          <div className="sbs-hero2__actions">
            <Btn to="/properties/" variant="gold">
              Browse listings
            </Btn>
            <Btn href={PHONE_HREF} variant="ghost">
              Call {PHONE_DISPLAY}
            </Btn>
          </div>
        </div>

        <a href={PHONE_HREF} className="sbs-hero2__agent" aria-label={`Call ${AGENT_NAME}`}>
          <img src={PORTRAIT} alt="" />
          <span>
            <b>{AGENT_NAME}</b>
            <small>REALTOR® · {BROKERAGE}</small>
            <em>
              <LuPhone size={14} aria-hidden="true" /> {PHONE_DISPLAY}
            </em>
          </span>
        </a>

        <SearchPanel />
      </div>
    </section>
  );
}
