import React, { useMemo, useState } from "react";
import { Link } from "gatsby";
import { FreeMode } from "swiper/modules";
import { Swiper, SwiperSlide } from "swiper/react";
import "swiper/css";
import "swiper/css/free-mode";

import { SectionHead, Btn } from "./Chrome";
import { Facts, priceLabel, townOf, useListings } from "./Listings";
import type { Property } from "../ppm/modules/property/types";

const ALL = "All homes";

function CaseCard({ property }: { property: Property }) {
  const to = `/properties/${property.slug}/`;
  return (
    <div className="sbs-case">
      <Link to={to} className="sbs-case__thumb" aria-label={property.title} tabIndex={-1}>
        {property.image ? <img src={property.image} srcSet={property.imageSrcSet} sizes="(max-width: 768px) 90vw, 40vw" alt={property.imageAlt} loading="lazy" /> : null}
      </Link>
      <div className="sbs-case__tags">
        <span>{townOf(property)}</span>
        <span>{property.type}</span>
        {property.availability ? <span>{property.availability}</span> : null}
      </div>
      <h3 className="sbs-case__title">
        <Link to={to}>{property.title}</Link>
      </h3>
      <p className="sbs-case__price">{priceLabel(property)}</p>
      <Facts property={property} />
    </div>
  );
}

/**
 * The template's "Case Studies" card slider, for listings: underline filter
 * tabs, a ghost "all" button, and drag-to-slide cards that run off the right
 * edge of the page. Loops and free-drags exactly as the template does.
 */
export function FeaturedSlider() {
  const all = useListings();
  const tabs = useMemo(() => [ALL, ...Array.from(new Set(all.map((p) => p.availability).filter(Boolean) as string[]))], [all]);
  const [tab, setTab] = useState(ALL);
  const items = tab === ALL ? all : all.filter((p) => p.availability === tab);

  if (!all.length) return null;

  return (
    <section id="listings" className="sbs-section sbs-cs">
      <div className="sbs-wrap">
        <SectionHead eyebrow="Featured listings" title="Homes worth a closer look" />

        <div className="sbs-cs__bar">
          <div className="sbs-cs__tabs" role="tablist" aria-label="Filter listings">
            {tabs.map((name) => (
              <button key={name} type="button" role="tab" aria-selected={tab === name} className={tab === name ? "is-on" : undefined} onClick={() => setTab(name)}>
                {name}
              </button>
            ))}
          </div>
          <Btn to="/properties/" variant="ghost">
            All listings
          </Btn>
        </div>

        <div className="sbs-cs__slider">
          <Swiper
            key={tab}
            modules={[FreeMode]}
            slidesPerView={1}
            spaceBetween={30}
            speed={1500}
            loop={items.length > 4}
            freeMode
            grabCursor
            observer
            observeParents
            breakpoints={{
              576: { slidesPerView: 1, spaceBetween: 30 },
              768: { slidesPerView: 2, spaceBetween: 30 },
              991: { slidesPerView: 3, spaceBetween: 40 },
              1200: { slidesPerView: 3, spaceBetween: 60 },
            }}
          >
            {items.map((property) => (
              <SwiperSlide key={property.slug}>
                <CaseCard property={property} />
              </SwiperSlide>
            ))}
          </Swiper>
        </div>
      </div>
    </section>
  );
}
