import React, { useEffect, useState } from "react";
import { LuAward, LuHammer, LuHouse, LuMapPin, LuQuote } from "react-icons/lu";

import { AGENT_NAME, BROKERAGE } from "../ppm/config/profile--business-name";
import { useInView } from "../ppm/modules/shared/useInView";
import { Btn } from "./Chrome";
import { PORTRAIT } from "./content";

const HIGHLIGHTS = [
  { icon: LuAward, title: "2023", text: "Rookie of the Year" },
  { icon: LuHammer, title: "Builder’s eye", text: "Raised around her family’s construction business" },
  { icon: LuMapPin, title: "Since 1999", text: "Rooted in the Treasure Valley" },
];

/** Round seal whose lettering turns slowly; the house mark stays still. */
function Seal() {
  return (
    <div className="sbs-ab__seal" aria-hidden="true">
      <svg viewBox="0 0 120 120" className="sbs-ab__seal-ring">
        <defs>
          <path id="sbs-seal-path" d="M60,60 m-44,0 a44,44 0 1,1 88,0 a44,44 0 1,1 -88,0" />
        </defs>
        <text>
          <textPath href="#sbs-seal-path" startOffset="0" textLength="270" lengthAdjust="spacing">
            SOLD BY SAJRA · BOISE · IDAHO · REALTOR® ·
          </textPath>
        </text>
      </svg>
      <LuHouse size={26} />
    </div>
  );
}

/**
 * About Sajra: an arched, framed portrait that reveals as it scrolls into view
 * (gold offset frame, spinning seal, floating tagline card) beside her story.
 * Everything is visible without JavaScript; the reveal only arms after mount.
 */
export default function About() {
  const { ref, inView } = useInView<HTMLDivElement>({ threshold: 0.2 });
  const [armed, setArmed] = useState(false);
  useEffect(() => setArmed(true), []);

  return (
    <section id="about" className="sbs-section sbs-ab">
      <div className="sbs-wrap sbs-ab__grid">
        <div ref={ref} className={`sbs-ab__art${armed ? " is-armed" : ""}${inView ? " is-in" : ""}`}>
          <div className="sbs-ab__frame" />
          <div className="sbs-ab__photo">
            <img src={PORTRAIT} alt={`${AGENT_NAME}, REALTOR®`} loading="lazy" />
          </div>
          <Seal />
          <div className="sbs-ab__float">
            <b>Construction-savvy.</b>
            <b>Detail-obsessed.</b>
            <span>
              {AGENT_NAME} · {BROKERAGE}
            </span>
          </div>
        </div>

        <div className="sbs-ab__copy">
          <span className="sbs-eyebrow">Meet Sajra</span>
          <h2 className="sbs-title sbs-title--lg">A Treasure Valley local, through and through</h2>

          <p className="sbs-ab__lead">
            Born in Germany to Bosnian parents, Sajra has called the Treasure Valley home since 1999. Her roots, and
            her community, run deep.
          </p>
          <p>
            She grew up around her family’s construction business, which gave her a builder’s eye. She can walk into a
            house and see what it could become.
          </p>
          <p>
            Named Rookie of the Year in 2023, she has helped clients buy, sell and invest across the valley, always
            with honesty, clear communication and an eye on lasting relationships. Away from work you’ll find her
            exploring Idaho with her fiancé Brendan and their dogs, and supporting local businesses.
          </p>

          <ul className="sbs-ab__facts">
            {HIGHLIGHTS.map(({ icon: Icon, title, text }) => (
              <li key={title}>
                <Icon size={22} aria-hidden="true" />
                <b>{title}</b>
                <span>{text}</span>
              </li>
            ))}
          </ul>

          <blockquote className="sbs-ab__quote">
            <LuQuote size={34} aria-hidden="true" />
            <p>My job is to make the process smooth, strategic, and genuinely enjoyable.</p>
            <cite>{AGENT_NAME}</cite>
          </blockquote>

          <div className="sbs-ab__actions">
            <Btn to="/contact/">Start a conversation</Btn>
            <Btn to="/properties/" variant="ghost">
              View listings
            </Btn>
          </div>
        </div>
      </div>
    </section>
  );
}
